// Writers for the generated Solidity libraries and the Foundry test of a
// t != 4 permutation.

import { hex, PRIME } from "../shared/field.ts";
import type { Params } from "../round-constants/round-constants.ts";
import type { BuildResult, Layout } from "./schedule.ts";

const HEADER = `// SPDX-License-Identifier: MIT
// This file is generated by generator/yul/generate.ts. Do not edit manually.
`;

const SECURITY =
  "Security: https://github.com/zemse/poseidon2-evm/blob/main/SECURITY.md";

// The t = 4 library keeps its hash_1 / hash_2 / hash_3 / poseidon2_core API.
// hash_n fold the initial linear layer and round 0's constants for their
// arity (entries) and continue in poseidon2_rest (rest), which
// poseidon2_core does not call, so a contract using only one of them carries
// one permutation.
export function renderHashLibrary(
  core: BuildResult,
  rest: BuildResult,
  entries: BuildResult[],
): string {
  const names = ["x", "y", "z"];
  const hashes = entries.map((entry, k) => {
    const n = k + 1;
    const args = names.slice(0, n).map((a) => `uint256 ${a}`);
    const lanes = [...names.slice(0, n), "0", "0"].slice(0, 3);
    lanes.push(`${n} << 64`);
    return `    function hash_${n}(${args.join(", ")}) internal pure returns (uint256) {
        uint256 s0;
        uint256 s1;
        uint256 s2;
        uint256 s3;
        assembly {
            // the initial linear layer and round 0's constants on [${lanes.join(", ")}]
${entry.lines.join("\n")}
        }
        return poseidon2_rest(s0, s1, s2, s3);
    }
`;
  });
  return `${HEADER}
pragma solidity >=0.6.0;

/// @notice Poseidon2 hash function library optimized in Yul assembly
/// @dev Internal functions can be inlined without deploying a contract
/// @dev Every add / mul in the assembly was checked by the generator's bound tracker to fit in uint256
/// ${SECURITY}
library LibPoseidon2Yul {
${hashes.join("\n")}
    function poseidon2_core(uint256 s0, uint256 s1, uint256 s2, uint256 s3) internal pure returns (uint256 result) {
        assembly {
${core.lines.join("\n")}
        }
    }

    /// @dev The permutation from round 0's S-boxes on: state0 .. state3 are the initial linear layer plus round 0's constants (any uint256)
    function poseidon2_rest(uint256 state0, uint256 state1, uint256 state2, uint256 state3) internal pure returns (uint256 result) {
        assembly {
${rest.lines.join("\n")}
        }
    }
}
`;
}

export function libraryName(t: number): string {
  return `LibPoseidon2YulT${t}`;
}

export function renderArrayLibrary(
  params: Params,
  layout: Layout,
  result: BuildResult,
): string {
  const { t, roundsF, roundsP } = params;
  const name = libraryName(t);
  const placement =
    layout.stackElements === t
      ? "the state is held in Yul locals"
      : `elements 0 .. ${layout.stackElements - 1} are held in Yul locals, the rest in the array`;
  const table =
    layout.diagFixed > 0
      ? `\n/// @dev ${layout.diagInMemory - layout.diagFixed} of the ${t} internal diag constants are kept in free memory (not allocated) and ${layout.diagFixed} at 0x40 and 0x60 to stay within the code size limit; the free memory pointer and the zero slot are restored after the internal rounds`
      : layout.diagInMemory > 0
        ? `\n/// @dev ${layout.diagInMemory} of the ${t} internal diag constants are kept in free memory (not allocated) to stay within the code size limit`
        : "";
  const scratch =
    layout.diagScratch > 0
      ? `\n/// @dev ${layout.diagScratch} internal diag constants are kept in the scratch space (0x00 - 0x3f) during the permutation`
      : "";
  return `${HEADER}
pragma solidity >=0.6.0;

/// @notice Poseidon2 permutation for BN254 with t = ${t}, Rf = ${roundsF}, Rp = ${roundsP}, optimized in Yul assembly
/// @dev Permutes \`state\` in place; inputs are reduced mod PRIME, ${placement}
/// @dev Every add / mul in the assembly was checked by the generator's bound tracker to fit in uint256${scratch}${table}
/// ${SECURITY}
library ${name} {
    function permute(uint256[${t}] memory state) internal pure {
        assembly {
${result.lines.join("\n")}
        }
    }
}
`;
}

export type Vector = { input: bigint[]; output: bigint[] };

// withHuff adds a fuzz test against the Huff permutation of the same width.
export function renderForgeTest(
  params: Params,
  vectors: Vector[],
  withHuff: boolean,
): string {
  const { t } = params;
  const lib = libraryName(t);
  const wrapper = `Poseidon2YulT${t}`;
  const cases = vectors
    .map(
      (v, i) => `
    function test_vector_${i}() public view {
        uint256[${t}] memory input = [
            ${v.input.map((x) => `uint256(${hex(x)})`).join(",\n            ")}
        ];
        uint256[${t}] memory expected = [
            ${v.output.map((x) => `uint256(${hex(x)})`).join(",\n            ")}
        ];
        assertEq(_permute(input), expected, "vector ${i}");
    }`,
    )
    .join("\n");
  return `${HEADER}pragma solidity ^0.8.13;

import {Test} from "forge-std/Test.sol";
${withHuff ? 'import {HuffDeployer} from "foundry-huff/HuffDeployer.sol";\n' : ""}import {${lib}} from "../src/bn254/yul/t${t}/${lib}.sol";

/// @notice Deployed in the test so the gas and code size of a contract using the library are measured
contract ${wrapper} {
    function permute(uint256[${t}] memory state) external pure returns (uint256[${t}] memory) {
        ${lib}.permute(state);
        return state;
    }
}

/// @notice Vectors come from the BigInt reference permutation in generator/shared/reference.ts
contract ${wrapper}Test is Test {
    uint256 constant PRIME = ${hex(PRIME)};

    ${wrapper} private perm;
${withHuff ? `    address private huff;\n` : ""}
    function setUp() public {
        perm = new ${wrapper}();
${withHuff ? `        huff = HuffDeployer.deploy("bn254/huff/t${t}/Poseidon2");\n` : ""}    }

    function _permute(uint256[${t}] memory input) internal view returns (uint256[${t}] memory) {
        return perm.permute(input);
    }
${
  withHuff
    ? `
    function _permuteHuff(uint256[${t}] memory input) internal view returns (uint256[${t}] memory out) {
        (bool ok, bytes memory ret) = huff.staticcall(abi.encode(input));
        require(ok, "huff permutation call failed");
        out = abi.decode(ret, (uint256[${t}]));
    }
`
    : ""
}
    function assertEq(uint256[${t}] memory a, uint256[${t}] memory b, string memory err) internal pure {
        for (uint256 i = 0; i < ${t}; i++) {
            assertEq(a[i], b[i], err);
        }
    }
${cases}

    /// @dev inputs at or above PRIME are reduced by the library
    function test_input_sanitization() public view {
        uint256[${t}] memory a;
        uint256[${t}] memory b;
        for (uint256 i = 0; i < ${t}; i++) {
            a[i] = i + 5;
            b[i] = PRIME + i + 5;
        }
        assertEq(_permute(a), _permute(b), "sanitization");
        for (uint256 i = 0; i < ${t}; i++) {
            a[i] = type(uint256).max % PRIME;
            b[i] = type(uint256).max;
        }
        assertEq(_permute(a), _permute(b), "sanitization max");
    }

    /// @dev the library leaves the free memory pointer and the zero slot as it found them
    function test_memory_kept() public pure {
        uint256[${t}] memory state;
        uint256 fmp;
        assembly {
            fmp := mload(0x40)
        }
        ${lib}.permute(state);
        uint256 fmpAfter;
        uint256 zero;
        assembly {
            fmpAfter := mload(0x40)
            zero := mload(0x60)
        }
        assertEq(fmpAfter, fmp, "free memory pointer");
        assertEq(zero, 0, "zero slot");
    }
${
  withHuff
    ? `
    /// @dev the Yul and Huff permutations of the same width must agree on any input
    /// forge-config: default.fuzz.runs = 1000
    function testFuzz_matches_huff(uint256[${t}] memory input) public view {
        assertEq(_permute(input), _permuteHuff(input), "yul != huff");
    }
`
    : ""
}}
`;
}
